# Code snippet to validate file type and ensure unique temporary file naming
import os

def is_pdf_file(filename):
    return filename.lower().endswith('.pdf')

def create_temp_file_path():
    return f'/tmp/temp_{os.urandom(16).hex()}.pdf'

# Example usage
filename = "example.pdf"
if is_pdf_file(filename):
    temp_pdf_path = create_temp_file_path()
    print(f"Temporary PDF path: {temp_pdf_path}")
else:
    print("Invalid file type. Only PDF files are allowed.")

# Check if the uploaded file is a PDF
def is_pdf(file):
    return file.filename.endswith('.pdf')

# Example usage
file = request.files['file']
assert is_pdf(file), "Uploaded file is not a PDF"
